-- Resources content: the exceptions guide names the exception page's
-- sections as built (docs/underwriting-traffic-redesign.md §17) — the last
-- section is "Resolve", and scheduling a makegood is a choice between
-- auto-fill and picking a break. Content only; no release note, since this
-- corrects a guide shipped the same day by 20261001120200.

select private.rc_release_guide(
  p_slug => 'underwriting-exceptions-and-makegoods',
  p_tool_key => 'underwriting',
  p_title => 'Exceptions and makegoods',
  p_summary => 'When a credit misses, decide what happens, schedule the makegood, and let it close itself.',
  p_screen_keys => array['underwriting.exceptions'],
  p_sort_order => 40,
  p_version_note => 'Step names match the page',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An exception appears the moment a host records an underwriting credit as missed or moved. There's nothing to check for: if a credit didn't air as scheduled, it's on this list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The list"}]},{"type":"paragraph","content":[{"type":"text","text":"Each row is one missed credit, with its makegood beside it. The filters follow the steps of resolving a miss, and the list opens on the first one with anything in it:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": no makegood yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order says the agency approves makegoods, and it hasn't answered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegood awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": a makegood exists; auto-fill will place it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegood scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": its break is chosen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolved","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working an exception"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the order needs the agency's approval, record its answer under "},{"type":"text","text":"Agency's answer","marks":[{"type":"bold"}]},{"type":"text","text":". Nothing schedules a makegood until then."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Makegood","marks":[{"type":"bold"}]},{"type":"text","text":", select "},{"type":"text","text":"Create a makegood","marks":[{"type":"bold"}]},{"type":"text","text":". By default auto-fill places it, ahead of regular credits. To choose the break yourself, select "},{"type":"text","text":"Pick a break now","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Resolve","marks":[{"type":"bold"}]},{"type":"text","text":", choose what happens: make it good, accept the alternate airing, waive, or close with no action. Rarer decisions are under "},{"type":"text","text":"More decisions","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An exception closes itself when its last makegood airs. There's no separate step to close it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A makegood counts toward the period the original credit missed, so it never counts as an extra unit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiving a credit needs an underwriting manager."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A resolved exception can be reopened from its own page."}]}]}]}]}$body$
);
